import React from 'react';
import { Link } from 'react-router-dom';
import SearchBar from '../components/SearchBar';

const Home = () => {
  const handleSearch = (query) => {
    // Actualmente no hay backend para búsquedas, podría filtrarse localmente
    console.log('Buscar:', query);
  };

  return (
    <main style={{ padding: '1rem' }}>
      <section style={{ textAlign: 'center', marginBottom: '2rem' }}>
        <h1>Práctica de Mecanografía</h1>
        <p>
          Mejora tu velocidad y precisión escribiendo textos diseñados para entrenar tus dedos.
          Elige un ejercicio y mide tus palabras por minuto (WPM) y precisión.
        </p>
        <Link to="/content">
          <button style={{ padding: '0.6rem 1rem', fontSize: '1rem' }}>Comenzar ejercicio</button>
        </Link>
      </section>

      <section>
        <h2>Buscar ejercicios</h2>
        <SearchBar onSearch={handleSearch} />
      </section>
    </main>
  );
};

export default Home;
